        // ===== Teclado =====
        ["Repetición del teclado"] = ("Keyboard repeat", "Repetição do teclado", "Tastaturwiederholung", "Répétition du clavier"),
        ["Retardo de repetición (ms)"] = ("Repeat delay (ms)", "Atraso de repetição (ms)", "Wiederholungsverzögerung (ms)", "Délai de répétition (ms)"),
        ["Velocidad de repetición (ms entre repeticiones)"] = ("Repeat speed (ms between repeats)", "Velocidade de repetição (ms entre repetições)", "Wiederholungsgeschwindigkeit (ms zwischen Wiederholungen)", "Vitesse de répétition (ms entre répétitions)"),
        ["Guardar en el registro"] = ("Save to registry", "Salvar no registro", "In der Registrierung speichern", "Enregistrer dans le registre"),
        ["Ajustá la repetición de teclas en milisegundos, igual que Filter Keys. Elegí un preset o escribí tus valores y dale a Aplicar: se aplican en vivo al instante (como FilterKeysSetter) y, con “Guardar en el registro”, quedan guardados para el próximo inicio de sesión."] = ("Adjust key repeat in milliseconds, just like Filter Keys. Pick a preset or type your values and hit Apply: they apply live instantly (like FilterKeysSetter) and, with “Save to registry”, they persist for the next sign-in.", "Ajuste a repetição das teclas em milissegundos, igual ao Filter Keys. Escolha um preset ou digite seus valores e clique em Aplicar: eles são aplicados ao vivo (como o FilterKeysSetter) e, com “Salvar no registro”, ficam salvos para o próximo login.", "Passen Sie die Tastenwiederholung in Millisekunden an, genau wie Filter Keys. Wählen Sie einen Preset oder geben Sie Ihre Werte ein und klicken Sie auf Anwenden: Sie werden sofort live angewendet (wie FilterKeysSetter) und mit „In der Registrierung speichern“ für die nächste Anmeldung gespeichert.", "Ajustez la répétition des touches en millisecondes, comme Filter Keys. Choisissez un préréglage ou saisissez vos valeurs puis cliquez sur Appliquer : elles s'appliquent en direct (comme FilterKeysSetter) et, avec « Enregistrer dans le registre », sont conservées pour la prochaine session."),
        ["Tiempo que hay que mantener una tecla presionada antes de que empiece a repetirse (50-500 ms es lo normal; menor = repite más rápido)."] = ("How long a key must be held before it starts repeating (50–500 ms is normal; lower = repeats faster).", "Quanto tempo uma tecla deve ficar pressionada antes de começar a repetir (50-500 ms é o normal; menor = repete mais rápido).", "Wie lange eine Taste gedrückt gehalten werden muss, bevor sie zu wiederholen beginnt (50–500 ms ist normal; niedriger = wiederholt schneller).", "Combien de temps une touche doit être maintenue avant de commencer à se répéter (50–500 ms est normal ; moins = répète plus vite)."),
        ["Intervalo entre repeticiones al mantener la tecla (10-50 ms = 100-20 repeticiones/segundo; menor = repite más rápido)."] = ("Interval between repeats while holding the key (10–50 ms = 100–20 repeats/second; lower = repeats faster).", "Intervalo entre repetições ao manter a tecla pressionada (10-50 ms = 100-20 repetições/segundo; menor = repete mais rápido).", "Intervall zwischen Wiederholungen bei gehaltener Taste (10–50 ms = 100–20 Wiederholungen/Sekunde; niedriger = wiederholt schneller).", "Intervalle entre répétitions en maintenant la touche (10–50 ms = 100–20 répétitions/seconde ; moins = répète plus vite)."),
        ["Ignorar pulsaciones menores a (ms)"] = ("Ignore presses shorter than (ms)", "Ignorar toques menores que (ms)", "Kürzere Tastendrücke ignorieren (ms)", "Ignorer les pressions plus courtes que (ms)"),
        ["Cuánto tiempo debe mantenerse presionada una tecla para que se registre (Slow Keys). 0 = acepta al instante (Windows aplica 1 ms como mínimo)."] = ("How long a key must be held to register (Slow Keys). 0 = accepts instantly (Windows applies 1 ms minimum).", "Quanto tempo uma tecla deve ficar pressionada para ser registrada (Slow Keys). 0 = aceita instantaneamente (o Windows aplica 1 ms no mínimo).", "Wie lange eine Taste gedrückt gehalten werden muss, um registriert zu werden (Slow Keys). 0 = sofort akzeptieren (Windows wendet mindestens 1 ms an).", "Combien de temps une touche doit être maintenue pour être enregistrée (Slow Keys). 0 = accepte instantanément (Windows applique 1 ms au minimum)."),
        ["Hacé clic acá y presioná una tecla..."] = ("Click here and press a key...", "Clique aqui e pressione uma tecla...", "Hier klicken und eine Taste drücken...", "Cliquez ici et appuyez sur une touche..."),
        ["Hotkey global"] = ("Global hotkey", "Hotkey global", "Globaler Hotkey", "Raccourci global"),
        ["Inicia o detiene el autoclicker desde cualquier aplicación. Hacé clic en el campo y presioná la tecla que quieras usar."] = ("Starts or stops the autoclicker from any application. Click the field and press the key you want to use.", "Inicia ou para o autoclicker de qualquer aplicativo. Clique no campo e pressione a tecla que quiser usar.", "Startet oder stoppt den Autoclicker aus jeder Anwendung. Klicken Sie auf das Feld und drücken Sie die gewünschte Taste.", "Démarre ou arrête l'autoclic depuis n'importe quelle application. Cliquez sur le champ et appuyez sur la touche de votre choix."),

