        // ===== Overlay de métricas =====
        ["Overlay de métricas"] = ("Metrics overlay", "Overlay de métricas", "Metriken-Overlay", "Superposition de métriques"),
        ["Superposición de métricas sobre tus juegos: FPS, uso de CPU/GPU, temperatura, frecuencia, watts y más. Configurá qué mostrar, los colores, la opacidad y los atajos."] = ("An on-screen metrics overlay for your games: FPS, CPU/GPU usage, temperature, frequency, watts and more. Configure what to show, the colors, the opacity and the hotkeys.", "Uma sobreposição de métricas nos seus jogos: FPS, uso de CPU/GPU, temperatura, frequência, watts e mais. Configure o que mostrar, as cores, a opacidade e os atalhos.", "Ein Metriken-Overlay für deine Spiele: FPS, CPU/GPU-Auslastung, Temperatur, Frequenz, Watt und mehr. Konfiguriere, was angezeigt wird, die Farben, die Deckkraft und die Hotkeys.", "Une superposition de métriques sur vos jeux : FPS, utilisation CPU/GPU, température, fréquence, watts et plus. Configurez ce qui est affiché, les couleurs, l'opacité et les raccourcis."),
        ["Activar overlay"] = ("Enable overlay", "Ativar overlay", "Overlay aktivieren", "Activer la superposition"),
        ["Activo. {0} muestra/oculta · {1} bloquea/desbloquea. El FPS corresponde al juego en primer plano."] = ("Active. {0} shows/hides · {1} locks/unlocks. The FPS is for the foreground game.", "Ativo. {0} mostra/oculta · {1} bloqueia/desbloqueia. O FPS é do jogo em primeiro plano.", "Aktiv. {0} zeigt/versteckt · {1} sperrt/entsperrt. Die FPS gelten für das aktive Spiel.", "Actif. {0} affiche/masque · {1} verrouille/déverrouille. Les FPS correspondent au jeu au premier plan."),
        ["Bloqueado"] = ("Locked", "Bloqueado", "Gesperrt", "Verrouillé"),
        ["Desbloqueado"] = ("Unlocked", "Desbloqueado", "Entsperrt", "Déverrouillé"),
        ["Inactivo. Activá el interruptor para superponer las métricas sobre tus juegos."] = ("Inactive. Turn on the switch to overlay the metrics on your games.", "Inativo. Ligue o interruptor para sobrepor as métricas aos seus jogos.", "Inaktiv. Aktivieren Sie den Schalter, um die Metriken über Ihre Spiele zu legen.", "Inactif. Activez l'interrupteur pour superposer les métriques sur vos jeux."),
        ["Atajos de teclado"] = ("Keyboard shortcuts", "Atalhos de teclado", "Tastenkürzel", "Raccourcis clavier"),
        ["Mostrar/ocultar overlay"] = ("Show/hide overlay", "Mostrar/ocultar overlay", "Overlay anzeigen/ausblenden", "Afficher/masquer la superposition"),
        ["Muestra u oculta la superposición desde cualquier aplicación."] = ("Shows or hides the overlay from any application.", "Mostra ou oculta a sobreposição de qualquer aplicativo.", "Zeigt oder blendet das Overlay aus jeder Anwendung ein/aus.", "Affiche ou masque la superposition depuis n'importe quelle application."),
        ["Bloquear/desbloquear overlay"] = ("Lock/unlock overlay", "Bloquear/desbloquear overlay", "Overlay sperren/entsperren", "Verrouiller/déverrouiller la superposition"),
        ["Desbloqueado: podés arrastrar la superposición con el mouse. Bloqueado: los clics pasan al juego."] = ("Unlocked: you can drag the overlay with the mouse. Locked: clicks pass through to the game.", "Desbloqueado: você pode arrastar a sobreposição com o mouse. Bloqueado: os cliques passam para o jogo.", "Entsperrt: Sie können das Overlay mit der Maus ziehen. Gesperrt: Klicks gehen an das Spiel.", "Déverrouillée : vous pouvez faire glisser la superposition avec la souris. Verrouillée : les clics passent au jeu."),
        ["Hacé clic en un atajo y presioná la nueva combinación (Ctrl+Alt+tecla recomendado). Esc cancela."] = ("Click a shortcut and press the new combination (Ctrl+Alt+key recommended). Esc cancels.", "Clique em um atalho e pressione a nova combinação (Ctrl+Alt+tecla recomendado). Esc cancela.", "Klicken Sie auf ein Kürzel und drücken Sie die neue Kombination (Ctrl+Alt+Taste empfohlen). Esc bricht ab.", "Cliquez sur un raccourci et appuyez sur la nouvelle combinaison (Ctrl+Alt+touche recommandé). Échap annule."),
        ["Opacidad"] = ("Opacity", "Opacidade", "Deckkraft", "Opacité"),
        ["Transparencia general de la superposición."] = ("General transparency of the overlay.", "Transparência geral da sobreposição.", "Allgemeine Transparenz des Overlays.", "Transparence générale de la superposition."),
        ["Esquina de la pantalla"] = ("Screen corner", "Canto da tela", "Bildschirmecke", "Coin de l'écran"),
        ["Ubicación por defecto (después podés arrastrarla con el atajo de desbloqueo)."] = ("Default position (you can then drag it with the unlock shortcut).", "Posição padrão (depois você pode arrastá-la com o atalho de desbloqueio).", "Standardposition (danach können Sie sie mit dem Entsperr-Kürzel ziehen).", "Position par défaut (vous pourrez ensuite la faire glisser avec le raccourci de déverrouillage)."),
        ["Arriba a la derecha"] = ("Top right", "Superior direito", "Oben rechts", "Haut droite"),
        ["Arriba a la izquierda"] = ("Top left", "Superior esquerdo", "Oben links", "Haut gauche"),
        ["Abajo a la derecha"] = ("Bottom right", "Inferior direito", "Unten rechts", "Bas droite"),
        ["Abajo a la izquierda"] = ("Bottom left", "Inferior esquerdo", "Unten links", "Bas gauche"),
        ["Colores de las métricas"] = ("Metric colors", "Cores das métricas", "Metrik-Farben", "Couleurs des métriques"),
        ["FPS"] = ("FPS", "FPS", "FPS", "FPS"),
