        ["Tabla binaria de plataforma Windows (WPBT) - Desactivar"] = ("Windows Platform Binary Table (WPBT) - Disable", "Tabela binária de plataforma Windows (WPBT) - Desativar", "Windows Platform Binary Table (WPBT) - Deaktivieren", "Table binaire de plateforme Windows (WPBT) - Désactiver"),
        ["Prevenir apps complementarias de dispositivos"] = ("Prevent companion apps for devices", "Prevenir aplicativos complementares de dispositivos", "Begleit-Apps für Geräte verhindern", "Empêcher les applications compagnes des périphériques"),
        ["Limpieza de disco - Ejecutar"] = ("Disk cleanup - Run", "Limpeza de disco - Executar", "Datenträgerbereinigung - Ausführen", "Nettoyage de disque - Exécuter"),
        ["Archivos temporales - Eliminar"] = ("Temporary files - Delete", "Arquivos temporários - Excluir", "Temporäre Dateien - Löschen", "Fichiers temporaires - Supprimer"),
        ["Detección automática de carpetas en Explorador - Desactivar"] = ("Automatic folder detection in Explorer - Disable", "Detecção automática de pastas no Explorer - Desativar", "Automatische Ordnererkennung im Explorer - Deaktivieren", "Détection automatique des dossiers dans l'Explorateur - Désactiver"),
