        ["Microsoft OneDrive - Eliminar"] = ("Microsoft OneDrive - Remove", "Microsoft OneDrive - Remover", "Microsoft OneDrive - Entfernen", "Microsoft OneDrive - Supprimer"),
        ["Inicio y Galería del Explorador - Desactivar"] = ("Explorer Home and Gallery - Disable", "Início e Galeria do Explorer - Desativar", "Explorer-Start und -Galerie - Deaktivieren", "Accueil et Galerie de l'Explorateur - Désactiver"),
        ["Efectos visuales - Configurar en Máximo rendimiento"] = ("Visual effects - Set to Best performance", "Efeitos visuais - Configurar para melhor desempenho", "Visuelle Effekte - Auf beste Leistung setzen", "Effets visuels - Régler sur les meilleures performances"),
