        ["Instalación automática de software Razer - Desactivar"] = ("Automatic Razer software installation - Disable", "Instalação automática de software Razer - Desativar", "Automatische Razer-Softwareinstallation - Deaktivieren", "Installation automatique du logiciel Razer - Désactiver"),
        ["Notificaciones del sistema y calendario - Desactivar"] = ("System and calendar notifications - Disable", "Notificações do sistema e calendário - Desativar", "System- und Kalenderbenachrichtigungen - Deaktivieren", "Notifications système et calendrier - Désactiver"),
        ["Lista de bloqueo de URL de Adobe - Activar"] = ("Adobe URL blocklist - Enable", "Lista de bloqueio de URL da Adobe - Ativar", "Adobe-URL-Sperrliste - Aktivieren", "Liste de blocage d'URL Adobe - Activer"),
        ["Menú contextual anterior - Activar"] = ("Previous context menu - Enable", "Menu de contexto anterior - Ativar", "Vorheriges Kontextmenü - Aktivieren", "Ancien menu contextuel - Activer"),
        ["IPv6 - Configurar IPv4 como preferido"] = ("IPv6 - Set IPv4 as preferred", "IPv6 - Configurar IPv4 como preferido", "IPv6 - IPv4 als bevorzugt festlegen", "IPv6 - Définir IPv4 comme préféré"),
