        ["Optimizaciones de pantalla completa - Desactivar"] = ("Fullscreen optimizations - Disable", "Otimizações de tela cheia - Desativar", "Vollbild-Optimierungen - Deaktivieren", "Optimisations plein écran - Désactiver"),
        ["O&O ShutUp10++ - Ejecutar"] = ("O&O ShutUp10++ - Run", "O&O ShutUp10++ - Executar", "O&O ShutUp10++ - Ausführen", "O&O ShutUp10++ - Exécuter"),

        // ===== Tweaks (Optimizaciones) - descripciones =====
        ["Borra documentos recientes, portapapeles e historial de ejecución."] = ("Clears recent documents, clipboard and run history.", "Limpa documentos recentes, área de transferência e histórico de execução.", "Löscht zuletzt verwendete Dokumente, Zwischenablage und Ausführungsverlauf.", "Efface les documents récents, le presse-papiers et l'historique d'exécution."),
        ["La hibernación está pensada para portátiles, ya que guarda la memoria antes de apagar el equipo. Realmente nunca debería usarse en escritorios."] = ("Hibernation is meant for laptops, since it saves memory before shutting down. It really should never be used on desktops.", "A hibernação foi feita para notebooks, pois salva a memória antes de desligar o computador. Realmente nunca deveria ser usada em desktops.", "Der Ruhezustand ist für Laptops gedacht, da er den Speicher vor dem Herunterfahren sichert. Auf Desktops sollte er wirklich nie verwendet werden.", "L'hibernation est conçue pour les portables, car elle sauvegarde la mémoire avant l'extinction. Elle ne devrait vraiment jamais être utilisée sur les postes fixes."),
        ["Elimina los molestos widgets en la parte inferior izquierda de la barra de tareas."] = ("Removes the annoying widgets at the bottom left of the taskbar.", "Remove os widgets irritantes na parte inferior esquerda da barra de tarefas.", "Entfernt die lästigen Widgets unten links in der Taskleiste.", "Supprime les widgets agaçants en bas à gauche de la barre des tâches."),
        ["Restaura el diseño antiguo del menú Inicio anterior al despliegue gradual del nuevo en 25H2. En versiones nuevas de Windows no funcionará."] = ("Restores the old Start menu layout from before the gradual rollout of the new one in 25H2. It will not work on newer Windows versions.", "Restaura o layout antigo do menu Iniciar, anterior à implantação gradual do novo na 25H2. Não funcionará em versões mais novas do Windows.", "Stellt das alte Startmenü-Layout wieder her, das vor der schrittweisen Einführung des neuen in 25H2 verwendet wurde. Auf neueren Windows-Versionen funktioniert es nicht.", "Rétablit l'ancienne disposition du menu Démarrer, antérieure au déploiement progressif de la nouvelle en 25H2. Cela ne fonctionnera pas sur les versions plus récentes de Windows."),
        ["No mostrará apps recomendadas de Microsoft Store al buscar en el menú Inicio."] = ("It will not show recommended Microsoft Store apps when searching in the Start menu.", "Não mostrará aplicativos recomendados da Microsoft Store ao pesquisar no menu Iniciar.", "Beim Suchen im Startmenü werden keine empfohlenen Microsoft-Store-Apps angezeigt.", "N'affichera plus d'applications recommandées du Microsoft Store lors de la recherche dans le menu Démarrer."),
        ["Desactiva el seguimiento de ubicación."] = ("Disables location tracking.", "Desativa o rastreamento de localização.", "Deaktiviert die Standortverfolgung.", "Désactive le suivi de localisation."),
        ["Configura algunos servicios en Manual y ajusta SvcHostSplitThresholdInKB para reducir significativamente la cantidad de procesos svchost.exe."] = ("Sets some services to Manual and adjusts SvcHostSplitThresholdInKB to significantly reduce the number of svchost.exe processes.", "Configura alguns serviços como Manual e ajusta SvcHostSplitThresholdInKB para reduzir significativamente a quantidade de processos svchost.exe.", "Setzt einige Dienste auf Manuell und passt SvcHostSplitThresholdInKB an, um die Anzahl der svchost.exe-Prozesse deutlich zu reduzieren.", "Règle certains services sur Manuel et ajuste SvcHostSplitThresholdInKB pour réduire considérablement le nombre de processus svchost.exe."),
        ["Detiene instalaciones promocionadas de apps y reduce sugerencias de contenido de Microsoft Store."] = ("Stops promoted app installations and reduces Microsoft Store content suggestions.", "Interrompe instalações promovidas de aplicativos e reduz sugestões de conteúdo da Microsoft Store.", "Stoppt beworbene App-Installationen und reduziert Inhaltsvorschläge des Microsoft Store.", "Arrête les installations d'applications promues et réduit les suggestions de contenu du Microsoft Store."),
        ["Desactiva la telemetría de Microsoft."] = ("Disables Microsoft telemetry.", "Desativa a telemetria da Microsoft.", "Deaktiviert die Microsoft-Telemetrie.", "Désactive la télémétrie de Microsoft."),
        ["Evita que Windows use tu ancho de banda para subir actualizaciones a otros equipos en internet o red local."] = ("Prevents Windows from using your bandwidth to upload updates to other computers on the internet or local network.", "Evita que o Windows use sua largura de banda para enviar atualizações a outros computadores na internet ou rede local.", "Verhindert, dass Windows Ihre Bandbreite nutzt, um Updates an andere Computer im Internet oder lokalen Netzwerk hochzuladen.", "Empêche Windows d'utiliser votre bande passante pour envoyer des mises à jour à d'autres ordinateurs sur Internet ou le réseau local."),
        ["Desactiva BitLocker."] = ("Disables BitLocker.", "Desativa o BitLocker.", "Deaktiviert BitLocker.", "Désactive BitLocker."),
        ["Crea un punto de restauración en tiempo de ejecución por si se necesita revertir modificaciones."] = ("Creates a restore point at runtime in case modifications need to be reverted.", "Cria um ponto de restauração em tempo de execução caso seja necessário reverter modificações.", "Erstellt zur Laufzeit einen Wiederherstellungspunkt, falls Änderungen rückgängig gemacht werden müssen.", "Crée un point de restauration à l'exécution au cas où des modifications devraient être annulées."),
        ["Habilita la opción de finalizar tarea al hacer clic derecho en un programa de la barra de tareas."] = ("Enables the end-task option when right-clicking a program on the taskbar.", "Habilita a opção de finalizar tarefa ao clicar com o botão direito em um programa da barra de tarefas.", "Aktiviert die Option „Aufgabe beenden“ beim Rechtsklick auf ein Programm in der Taskleiste.", "Active l'option de terminer la tâche en cliquant avec le bouton droit sur un programme de la barre des tâches."),
        ["WPBT permite que el fabricante ejecute programas al iniciar, como software antirrobo o instalaciones forzadas sin consentimiento. Riesgo de seguridad."] = ("WPBT lets the manufacturer run programs at startup, such as anti-theft software or forced installs without consent. Security risk.", "WPBT permite que o fabricante execute programas na inicialização, como software antifurto ou instalações forçadas sem consentimento. Risco de segurança.", "WPBT erlaubt dem Hersteller, Programme beim Start auszuführen, etwa Diebstahlschutz-Software oder erzwungene Installationen ohne Zustimmung. Sicherheitsrisiko.", "WPBT permet au fabricant d'exécuter des programmes au démarrage, comme un logiciel antivol ou des installations forcées sans consentement. Risque de sécurité."),
        ["Evita que se instale software adicional al conectar dispositivos (ej. anuncios al conectar un monitor). Riesgo de seguridad."] = ("Prevents extra software from being installed when connecting devices (e.g. ads when plugging in a monitor). Security risk.", "Evita a instalação de software adicional ao conectar dispositivos (ex.: anúncios ao conectar um monitor). Risco de segurança.", "Verhindert die Installation zusätzlicher Software beim Anschließen von Geräten (z. B. Werbung beim Anschließen eines Monitors). Sicherheitsrisiko.", "Empêche l'installation de logiciels supplémentaires lors de la connexion de périphériques (ex. : publicités en branchant un moniteur). Risque de sécurité."),
        ["Ejecuta la limpieza del disco C: y elimina actualizaciones de Windows antiguas."] = ("Runs disk cleanup on drive C: and removes old Windows updates.", "Executa a limpeza do disco C: e remove atualizações antigas do Windows.", "Führt die Datenträgerbereinigung auf Laufwerk C: aus und entfernt alte Windows-Updates.", "Exécute le nettoyage du disque C: et supprime les anciennes mises à jour Windows."),
        ["Borra las carpetas TEMP."] = ("Clears the TEMP folders.", "Limpa as pastas TEMP.", "Leert die TEMP-Ordner.", "Vide les dossiers TEMP."),
        ["El Explorador intenta adivinar el tipo de carpeta según su contenido, ralentizando la navegación. ¡ADVERTENCIA! Desactivará la agrupación del Explorador."] = ("Explorer tries to guess the folder type based on its content, slowing navigation. WARNING! It will disable Explorer grouping.", "O Explorer tenta adivinhar o tipo de pasta pelo conteúdo, retardando a navegação. ATENÇÃO! Desativará o agrupamento do Explorer.", "Der Explorer versucht, den Ordnertyp anhand des Inhalts zu erraten, was die Navigation verlangsamt. WARNUNG! Es deaktiviert die Gruppierung des Explorers.", "L'Explorateur essaie de deviner le type de dossier selon son contenu, ralentissant la navigation. AVERTISSEMENT ! Cela désactivera le regroupement de l'Explorateur."),
        ["Desactiva varias molestias como Brave Rewards, Leo AI, Crypto Wallet y VPN."] = ("Disables several annoyances like Brave Rewards, Leo AI, Crypto Wallet and VPN.", "Desativa várias irritações como Brave Rewards, Leo AI, Crypto Wallet e VPN.", "Deaktiviert mehrere Störfaktoren wie Brave Rewards, Leo AI, Crypto Wallet und VPN.", "Désactive plusieurs nuisances comme Brave Rewards, Leo AI, Crypto Wallet et VPN."),
        ["Desactiva las advertencias al lanzar archivos RDP sin firmar introducidas en las últimas actualizaciones."] = ("Disables the warnings when launching unsigned RDP files introduced in recent updates.", "Desativa os avisos ao abrir arquivos RDP não assinados, introduzidos nas últimas atualizações.", "Deaktiviert die Warnungen beim Starten unsignierter RDP-Dateien, die in den letzten Updates eingeführt wurden.", "Désactive les avertissements lors du lancement de fichiers RDP non signés, introduits dans les dernières mises à jour."),
        ["Desactiva varias opciones de telemetría, popups y otras molestias en Edge."] = ("Disables several telemetry options, popups and other annoyances in Edge.", "Desativa várias opções de telemetria, popups e outras irritações no Edge.", "Deaktiviert mehrere Telemetrie-Optionen, Popups und andere Störfaktoren in Edge.", "Désactive plusieurs options de télémétrie, fenêtres popup et autres nuisances dans Edge."),
        ["Desinstala Microsoft Edge creando un archivo dummy MicrosoftEdge.exe que engaña al desinstalador oficial para una eliminación a nivel de sistema."] = ("Uninstalls Microsoft Edge by creating a dummy MicrosoftEdge.exe file that tricks the official uninstaller into a system-level removal.", "Desinstala o Microsoft Edge criando um arquivo dummy MicrosoftEdge.exe que engana o desinstalador oficial para uma remoção em nível de sistema.", "Deinstalliert Microsoft Edge, indem eine Dummy-Datei MicrosoftEdge.exe erstellt wird, die den offiziellen Deinstaller zu einer Entfernung auf Systemebene verleitet.", "Désinstalle Microsoft Edge en créant un fichier factice MicrosoftEdge.exe qui trompe le désinstalleur officiel pour une suppression au niveau du système."),
        ["Esencial para equipos con dual-boot. Corrige la sincronización horaria con sistemas Linux."] = ("Essential for dual-boot machines. Fixes time synchronization with Linux systems.", "Essencial para computadores com dual-boot. Corrige a sincronização de horário com sistemas Linux.", "Unverzichtbar für Dual-Boot-Systeme. Korrigiert die Zeitsynchronisierung mit Linux-Systemen.", "Essentiel pour les machines en double démarrage. Corrige la synchronisation de l'heure avec les systèmes Linux."),
        ["Deniega permisos para eliminar archivos de usuario de OneDrive, usa su desinstalador para quitarlo y restaura los permisos."] = ("Denies permissions to delete OneDrive user files, uses its uninstaller to remove it and restores the permissions.", "Nega permissões para excluir arquivos de usuário do OneDrive, usa o desinstalador para removê-lo e restaura as permissões.", "Verweigert Berechtigungen zum Löschen von OneDrive-Benutzerdateien, verwendet den Deinstaller zur Entfernung und stellt die Berechtigungen wieder her.", "Refuse les autorisations de supprimer les fichiers utilisateur OneDrive, utilise son désinstalleur pour le retirer puis restaure les autorisations."),
        ["Elimina Inicio y Galería del Explorador y establece Este PC como predeterminado."] = ("Removes Explorer Home and Gallery and sets This PC as default.", "Remove Início e Galeria do Explorer e define Este PC como padrão.", "Entfernt Explorer-Start und -Galerie und legt „Dieser PC“ als Standard fest.", "Supprime l'Accueil et la Galerie de l'Explorateur et définit Ce PC par défaut."),
        ["Configura las preferencias del sistema a rendimiento. Puedes hacerlo manualmente con sysdm.cpl."] = ("Sets system preferences to performance. You can do it manually with sysdm.cpl.", "Configura as preferências do sistema para desempenho. Você pode fazer manualmente com sysdm.cpl.", "Setzt die Systemeinstellungen auf Leistung. Sie können es manuell mit sysdm.cpl tun.", "Règle les préférences système sur les performances. Vous pouvez le faire manuellement avec sysdm.cpl."),
        ["Desactiva el almacenamiento reservado de Windows (7-10 GB para actualizaciones). Solo recomendado en discos pequeños. Re-activar antes de grandes actualizaciones."] = ("Disables Windows reserved storage (7-10 GB for updates). Only recommended on small disks. Re-enable before major updates.", "Desativa o armazenamento reservado do Windows (7-10 GB para atualizações). Recomendado apenas em discos pequenos. Reative antes de grandes atualizações.", "Deaktiviert den reservierten Windows-Speicher (7-10 GB für Updates). Nur auf kleinen Festplatten empfohlen. Vor großen Updates wieder aktivieren.", "Désactive le stockage réservé de Windows (7-10 Go pour les mises à jour). Recommandé uniquement sur les petits disques. Réactivez avant les mises à jour majeures."),
        ["Storage Sense elimina archivos temporales automáticamente."] = ("Storage Sense deletes temporary files automatically.", "O Storage Sense exclui arquivos temporários automaticamente.", "Storage Sense löscht temporäre Dateien automatisch.", "Storage Sense supprime automatiquement les fichiers temporaires."),
        ["Elimina y desactiva todas las funciones y paquetes de IA."] = ("Removes and disables all AI features and packages.", "Remove e desativa todas as funções e pacotes de IA.", "Entfernt und deaktiviert alle KI-Funktionen und -Pakete.", "Supprime et désactive toutes les fonctionnalités et tous les packages d'IA."),
        ["Bloquea TODAS las instalaciones de software Razer. El hardware funciona bien sin software."] = ("Blocks ALL Razer software installations. The hardware works fine without software.", "Bloqueia TODAS as instalações de software Razer. O hardware funciona bem sem software.", "Blockiert ALLE Razer-Softwareinstallationen. Die Hardware funktioniert ohne Software einwandfrei.", "Bloque TOUTES les installations de logiciel Razer. Le matériel fonctionne très bien sans logiciel."),
        ["Desactiva todas las notificaciones INCLUYENDO el calendario."] = ("Disables all notifications INCLUDING the calendar.", "Desativa todas as notificações INCLUINDO o calendário.", "Deaktiviert alle Benachrichtigungen EINSCHLIESSLICH des Kalenders.", "Désactive toutes les notifications, Y COMPRIS le calendrier."),
        ["Reduce interrupciones bloqueando selectivamente conexiones a servidores de activación y telemetría de Adobe."] = ("Reduces interruptions by selectively blocking connections to Adobe activation and telemetry servers.", "Reduz interrupções bloqueando seletivamente conexões aos servidores de ativação e telemetria da Adobe.", "Reduziert Unterbrechungen, indem Verbindungen zu Adobes Aktivierungs- und Telemetrieservern selektiv blockiert werden.", "Réduit les interruptions en bloquant sélectivement les connexions aux serveurs d'activation et de télémétrie d'Adobe."),
        ["Restaura el menú contextual clásico del Explorador, reemplazando la versión simplificada de Windows 11."] = ("Restores the classic Explorer context menu, replacing the simplified Windows 11 version.", "Restaura o menu de contexto clássico do Explorer, substituindo a versão simplificada do Windows 11.", "Stellt das klassische Explorer-Kontextmenü wieder her und ersetzt die vereinfachte Windows-11-Version.", "Rétablit le menu contextuel classique de l'Explorateur, remplaçant la version simplifiée de Windows 11."),
        ["Configurar la preferencia IPv4 puede tener beneficios de latencia y seguridad en redes privadas sin IPv6."] = ("Setting IPv4 preference can have latency and security benefits on private networks without IPv6.", "Configurar a preferência IPv4 pode trazer benefícios de latência e segurança em redes privadas sem IPv6.", "Die IPv4-Präferenz kann auf privaten Netzwerken ohne IPv6 Latenz- und Sicherheitsvorteile bringen.", "Définir la préférence IPv4 peut apporter des bénéfices de latence et de sécurité sur les réseaux privés sans IPv6."),
        ["Teredo es un túnel IPv6 que puede causar latencia adicional, aunque puede causar problemas con algunos juegos."] = ("Teredo is an IPv6 tunnel that can cause extra latency, although it can cause problems with some games.", "Teredo é um túnel IPv6 que pode causar latência adicional, embora possa causar problemas com alguns jogos.", "Teredo ist ein IPv6-Tunnel, der zusätzliche Latenz verursachen kann, aber auch Probleme mit einigen Spielen.", "Teredo est un tunnel IPv6 qui peut ajouter de la latence, bien qu'il puisse causer des problèmes avec certains jeux."),
        ["Desactiva IPv6."] = ("Disables IPv6.", "Desativa o IPv6.", "Deaktiviert IPv6.", "Désactive IPv6."),
        ["Desactiva todas las apps de Microsoft Store en segundo plano, lo que debe hacerse individualmente desde Windows 11."] = ("Disables all Microsoft Store apps running in the background, which must be done individually since Windows 11.", "Desativa todos os aplicativos da Microsoft Store em segundo plano, o que deve ser feito individualmente desde o Windows 11.", "Deaktiviert alle Microsoft-Store-Apps im Hintergrund, was seit Windows 11 einzeln erfolgen muss.", "Désactive toutes les applications du Microsoft Store en arrière-plan, ce qui doit être fait individuellement depuis Windows 11."),
        ["Desactiva FSO en todas las aplicaciones. NOTA: Desactivará la gestión de color en pantalla completa exclusiva."] = ("Disables FSO in all applications. NOTE: It will disable exclusive fullscreen color management.", "Desativa FSO em todos os aplicativos. NOTA: Desativará o gerenciamento de cores em tela cheia exclusiva.", "Deaktiviert FSO in allen Anwendungen. HINWEIS: Das deaktiviert die exklusive Farbverwaltung im Vollbildmodus.", "Désactive FSO dans toutes les applications. REMARQUE : cela désactivera la gestion des couleurs en plein écran exclusif."),
        ["Ejecuta O&O ShutUp10++ para aplicar su colección de tweaks de privacidad."] = ("Runs O&O ShutUp10++ to apply its collection of privacy tweaks.", "Executa o O&O ShutUp10++ para aplicar sua coleção de tweaks de privacidade.", "Führt O&O ShutUp10++ aus, um seine Sammlung von Datenschutz-Tweaks anzuwenden.", "Exécute O&O ShutUp10++ pour appliquer sa collection de réglages de confidentialité."),

