        // ===== Debloat: descripciones de tweaks =====
        ["Elimina el asistente de voz de Microsoft (discontinuado)."] = ("Removes Microsoft's voice assistant (discontinued).", "Remove o assistente de voz da Microsoft (descontinuado).", "Entfernt den Sprachassistenten von Microsoft (eingestellt).", "Supprime l'assistant vocal de Microsoft (abandonné)."),
        ["Elimina el clásico juego de King preinstalado en Windows."] = ("Removes the classic King game preinstalled on Windows.", "Remove o clássico jogo da King pré-instalado no Windows.", "Entfernt das klassische King-Spiel, das unter Windows vorinstalliert ist.", "Supprime le jeu classique de King préinstallé sur Windows."),
        ["Elimina el editor de video de Microsoft."] = ("Removes Microsoft's video editor.", "Remove o editor de vídeo da Microsoft.", "Entfernt den Video-Editor von Microsoft.", "Supprime l'éditeur vidéo de Microsoft."),
        ["Elimina la colección de solitario de Microsoft."] = ("Removes Microsoft's Solitaire Collection.", "Remove a Coleção Solitário da Microsoft.", "Entfernt die Solitaire-Sammlung von Microsoft.", "Supprime la Collection Solitaire de Microsoft."),
        ["Elimina la versión UWP de Skype (discontinuada)."] = ("Removes the UWP version of Skype (discontinued).", "Remove a versão UWP do Skype (descontinuada).", "Entfernt die UWP-Version von Skype (eingestellt).", "Supprime la version UWP de Skype (abandonnée)."),
        ["Elimina la versión UWP de OneNote."] = ("Removes the UWP version of OneNote.", "Remove a versão UWP do OneNote.", "Entfernt die UWP-Version von OneNote.", "Supprime la version UWP de OneNote."),
        ["Elimina las versiones de Microsoft Teams (nueva y clásica)."] = ("Removes both Microsoft Teams versions (new and classic).", "Remove as duas versões do Microsoft Teams (nova e clássica).", "Entfernt beide Microsoft-Teams-Versionen (neu und klassisch).", "Supprime les deux versions de Microsoft Teams (nouvelle et classique)."),
        ["Elimina la app preinstalada de TikTok."] = ("Removes the preinstalled TikTok app.", "Remove o aplicativo pré-instalado do TikTok.", "Entfernt die vorinstallierte TikTok-App.", "Supprime l'application TikTok préinstallée."),
        ["Elimina la app preinstalada de Spotify."] = ("Removes the preinstalled Spotify app.", "Remove o aplicativo pré-instalado do Spotify.", "Entfernt die vorinstallierte Spotify-App.", "Supprime l'application Spotify préinstallée."),
        ["Elimina la app de correo y calendario (discontinuada, reemplazada por Outlook)."] = ("Removes the Mail and Calendar app (discontinued, replaced by Outlook).", "Remove o aplicativo de Correio e calendário (descontinuado, substituído pelo Outlook).", "Entfernt die E-Mail-und-Kalender-App (eingestellt, durch Outlook ersetzt).", "Supprime l'application Courrier et calendrier (abandonnée, remplacée par Outlook)."),
        ["Elimina la app de noticias de Microsoft."] = ("Removes the Microsoft News app.", "Remove o aplicativo de Notícias da Microsoft.", "Entfernt die Microsoft-News-App.", "Supprime l'application Actualités de Microsoft."),
        ["Elimina la app de video de Microsoft."] = ("Removes Microsoft's video app.", "Remove o aplicativo de vídeo da Microsoft.", "Entfernt die Video-App von Microsoft.", "Supprime l'application vidéo de Microsoft."),
        ["Elimina el hub de acceso a las aplicaciones de Office."] = ("Removes the Office apps hub.", "Remove o hub de acesso aos aplicativos do Office.", "Entfernt den Hub für Office-Apps.", "Supprime le hub d'accès aux applications Office."),
        ["Elimina la integración con el teléfono (antes Tu Teléfono)."] = ("Removes phone integration (formerly Your Phone).", "Remove a integração com o telefone (antes Meu Telefone).", "Entfernt die Telefonintegration (früher Dein Smartphone).", "Supprime l'intégration avec le téléphone (anciennement Votre téléphone)."),
        ["Elimina la app de Xbox. OJO: es necesaria para instalar algunos juegos de PC."] = ("Removes the Xbox app. NOTE: it is required to install some PC games.", "Remove o aplicativo do Xbox. ATENÇÃO: é necessário para instalar alguns jogos de PC.", "Entfernt die Xbox-App. ACHTUNG: Sie wird zum Installieren einiger PC-Spiele benötigt.", "Supprime l'application Xbox. ATTENTION : elle est nécessaire pour installer certains jeux PC."),
        ["Elimina el asistente de IA integrado de Windows."] = ("Removes Windows' built-in AI assistant.", "Remove o assistente de IA integrado do Windows.", "Entfernt den integrierten KI-Assistenten von Windows.", "Supprime l'assistant IA intégré de Windows."),
        ["Desactiva varias molestias como Brave Rewards, Leo AI, Crypto Wallet y VPN."] = ("Disables several annoyances like Brave Rewards, Leo AI, Crypto Wallet and VPN.", "Desativa várias irritações como Brave Rewards, Leo AI, Carteira Cripto e VPN.", "Deaktiviert mehrere Störungen wie Brave Rewards, Leo AI, Crypto-Wallet und VPN.", "Désactive plusieurs désagréments comme Brave Rewards, Leo AI, Crypto Wallet et le VPN."),
        ["Desactiva varias opciones de telemetría, popups y otras molestias en Edge."] = ("Disables several telemetry options, popups and other annoyances in Edge.", "Desativa várias opções de telemetria, pop-ups e outras irritações no Edge.", "Deaktiviert mehrere Telemetrie-Optionen, Popups und andere Störungen in Edge.", "Désactive plusieurs options de télémétrie, pop-ups et autres désagréments dans Edge."),
        ["Desinstala Microsoft Edge creando un archivo dummy MicrosoftEdge.exe que engaña al desinstalador oficial para una eliminación a nivel de sistema."] = ("Uninstalls Microsoft Edge by creating a dummy MicrosoftEdge.exe that tricks the official uninstaller into a system-wide removal.", "Desinstala o Microsoft Edge criando um arquivo dummy MicrosoftEdge.exe que engana o desinstalador oficial para uma remoção em nível de sistema.", "Deinstalliert Microsoft Edge, indem eine Dummy-Datei MicrosoftEdge.exe erstellt wird, die den offiziellen Deinstaller zu einer systemweiten Entfernung verleitet.", "Désinstalle Microsoft Edge en créant un fichier factice MicrosoftEdge.exe qui trompe le désinstalleur officiel pour une suppression au niveau du système."),
        ["Deniega permisos para eliminar archivos de usuario de OneDrive, usa su desinstalador para quitarlo y restaura los permisos."] = ("Denies permissions to remove OneDrive user files, uses its uninstaller to remove it and restores the permissions.", "Nega permissões para remover arquivos de usuário do OneDrive, usa o desinstalador para removê-lo e restaura as permissões.", "Verweigert Berechtigungen zum Entfernen von OneDrive-Benutzerdateien, verwendet den Deinstaller und stellt die Berechtigungen wieder her.", "Refuse les autorisations pour supprimer les fichiers utilisateur de OneDrive, utilise son désinstalleur pour le supprimer et restaure les autorisations."),
        ["Elimina y desactiva todas las funciones y paquetes de IA."] = ("Removes and disables all AI features and packages.", "Remove e desativa todos os recursos e pacotes de IA.", "Entfernt und deaktiviert alle KI-Funktionen und -Pakete.", "Supprime et désactive toutes les fonctionnalités et packages IA."),
        ["Desinstala el paquete Microsoft.XboxGamingOverlay (la app de la barra de juegos), cerrando antes sus procesos. Windows puede reinstalarla con las actualizaciones. Revertir abre la Microsoft Store para reinstalarla."] = ("Uninstalls the Microsoft.XboxGamingOverlay package (the Game Bar app), closing its processes first. Windows may reinstall it with updates. Reverting opens the Microsoft Store to reinstall it.", "Desinstala o pacote Microsoft.XboxGamingOverlay (o aplicativo da Barra de Jogo), fechando antes seus processos. O Windows pode reinstalá-lo com as atualizações. Reverter abre a Microsoft Store para reinstalá-lo.", "Deinstalliert das Paket Microsoft.XboxGamingOverlay (die Game-Bar-App), nachdem zuerst ihre Prozesse geschlossen wurden. Windows kann sie mit Updates neu installieren. Rückgängig machen öffnet den Microsoft Store zur Neuinstallation.", "Désinstalle le package Microsoft.XboxGamingOverlay (l'application Barre de jeu), en fermant d'abord ses processus. Windows peut le réinstaller avec les mises à jour. L'annulation ouvre le Microsoft Store pour le réinstaller."),
        ["Elimina los molestos widgets en la parte inferior izquierda de la barra de tareas."] = ("Removes the annoying widgets in the bottom-left corner of the taskbar.", "Remove os irritantes widgets no canto inferior esquerdo da barra de tarefas.", "Entfernt die störenden Widgets in der unteren linken Ecke der Taskleiste.", "Supprime les widgets gênants dans le coin inférieur gauche de la barre des tâches."),
        ["Bloquea TODAS las instalaciones de software Razer. El hardware funciona bien sin software."] = ("Blocks ALL Razer software installs. The hardware works fine without software.", "Bloqueia TODAS as instalações de software da Razer. O hardware funciona bem sem software.", "Blockiert ALLE Razer-Softwareinstallationen. Die Hardware funktioniert auch ohne Software.", "Bloque TOUTES les installations de logiciels Razer. Le matériel fonctionne très bien sans logiciel."),
        ["Reduce interrupciones bloqueando selectivamente conexiones a servidores de activación y telemetría de Adobe."] = ("Reduces interruptions by selectively blocking connections to Adobe activation and telemetry servers.", "Reduz interrupções bloqueando seletivamente conexões a servidores de ativação e telemetria da Adobe.", "Reduziert Unterbrechungen, indem Verbindungen zu Adobe-Aktivierungs- und Telemetrieservern selektiv blockiert werden.", "Réduit les interruptions en bloquant sélectivement les connexions aux serveurs d'activation et de télémétrie d'Adobe."),

        // ===== Herramientas de reparación (Reparación) =====
        ["SFC - Escaneo de archivos de sistema"] = ("SFC - System file scan", "SFC - Verificação de arquivos do sistema", "SFC - Systemdatei-Überprüfung", "SFC - Analyse des fichiers système"),
        ["Repara archivos de sistema corruptos o dañados en Windows. Escanea todos los archivos protegidos del sistema y reemplaza las versiones incorrectas con las versiones correctas."] = ("Repairs corrupted or damaged system files in Windows. Scans all protected system files and replaces incorrect versions with the correct ones.", "Repara arquivos de sistema corrompidos ou danificados no Windows. Examina todos os arquivos protegidos do sistema e substitui as versões incorretas pelas corretas.", "Repariert beschädigte oder fehlerhafte Systemdateien in Windows. Durchsucht alle geschützten Systemdateien und ersetzt falsche Versionen durch die richtigen.", "Réparer les fichiers système corrompus ou endommagés de Windows. Analyse tous les fichiers système protégés et remplace les versions incorrectes par les bonnes."),
        ["DISM - Reparación de imagen de Windows"] = ("DISM - Windows image repair", "DISM - Reparação da imagem do Windows", "DISM - Windows-Abbildreparatur", "DISM - Réparation de l'image Windows"),
        ["Repara la imagen de Windows cuando SFC no puede solucionar el problema. Descarga archivos correctos desde Windows Update si es necesario."] = ("Repairs the Windows image when SFC cannot fix the problem. Downloads correct files from Windows Update if needed.", "Repara a imagem do Windows quando o SFC não consegue resolver o problema. Baixa arquivos corretos do Windows Update se necessário.", "Repariert das Windows-Abbild, wenn SFC das Problem nicht beheben kann. Lädt bei Bedarf korrekte Dateien von Windows Update herunter.", "Réparer l'image Windows lorsque SFC ne peut pas résoudre le problème. Télécharge les fichiers corrects depuis Windows Update si nécessaire."),
        ["CHKDSK - Verificación de disco"] = ("CHKDSK - Disk check", "CHKDSK - Verificação de disco", "CHKDSK - Datenträgerprüfung", "CHKDSK - Vérification du disque"),
        ["Verifica y repara errores en el sistema de archivos y sectores dañados del disco duro o SSD. Puede requerir reinicio si el disco está en uso."] = ("Checks and repairs file system errors and bad sectors on the hard drive or SSD. May require a restart if the disk is in use.", "Verifica e repara erros no sistema de arquivos e setores danificados do disco rígido ou SSD. Pode exigir reinicialização se o disco estiver em uso.", "Überprüft und repariert Dateisystemfehler und beschädigte Sektoren der Festplatte oder SSD. Kann einen Neustart erfordern, wenn die Festplatte in Gebrauch ist.", "Vérifie et répare les erreurs du système de fichiers et les secteurs défectueux du disque dur ou SSD. Peut nécessiter un redémarrage si le disque est en cours d'utilisation."),
        ["Reparación del almacén de componentes"] = ("Component store repair", "Reparação do repositório de componentes", "Komponentenspeicher-Reparatur", "Réparation du magasin de composants"),
        ["Limpia el almacén de componentes de Windows (WinSxS) para liberar espacio y eliminar versiones obsoletas de archivos del sistema."] = ("Cleans the Windows component store (WinSxS) to free space and remove obsolete versions of system files.", "Limpa o repositório de componentes do Windows (WinSxS) para liberar espaço e remover versões obsoletas de arquivos do sistema.", "Bereinigt den Windows-Komponentenspeicher (WinSxS), um Speicherplatz freizugeben und veraltete Versionen von Systemdateien zu entfernen.", "Nettoie le magasin de composants Windows (WinSxS) pour libérer de l'espace et supprimer les versions obsolètes des fichiers système."),
        ["Restablecer configuración de red"] = ("Reset network configuration", "Redefinir configuração de rede", "Netzwerkkonfiguration zurücksetzen", "Réinitialiser la configuration réseau"),
        ["Restablece el stack de red de Windows a su estado predeterminado. Soluciona problemas de conectividad, DNS y adaptadores de red."] = ("Resets the Windows network stack to its default state. Fixes connectivity, DNS and network adapter problems.", "Redefine a pilha de rede do Windows ao estado padrão. Soluciona problemas de conectividade, DNS e adaptadores de rede.", "Setzt den Windows-Netzwerkstapel auf den Standardzustand zurück. Behebt Probleme mit Konnektivität, DNS und Netzwerkadaptern.", "Réinitialise la pile réseau de Windows à son état par défaut. Résout les problèmes de connectivité, de DNS et d'adaptateurs réseau."),
        ["Reparar Windows Store"] = ("Repair Windows Store", "Reparar Windows Store", "Windows Store reparieren", "Réparer le Windows Store"),
        ["Re-registra todas las aplicaciones de la Store. Las apps en uso o con una versión más nueva se omiten sin errores."] = ("Re-registers all Store apps. Apps in use or with a newer version are skipped without errors.", "Re-registra todos os aplicativos da Store. Aplicativos em uso ou com versão mais nova são ignorados sem erros.", "Registriert alle Store-Apps neu. Apps in Verwendung oder mit neuerer Version werden ohne Fehler übersprungen.", "Réenregistre toutes les applications du Store. Les applications en cours d'utilisation ou avec une version plus récente sont ignorées sans erreur."),
        ["Reparar perfil de usuario"] = ("Repair user profile", "Reparar perfil de usuário", "Benutzerprofil reparieren", "Réparer le profil utilisateur"),
        ["Escanea los perfiles de usuario del registro (ProfileList) y corrige el marcador de corrupción (State) cuando la carpeta del perfil está intacta. Útil para el error 'No podemos iniciar sesión en tu cuenta'."] = ("Scans user profiles in the registry (ProfileList) and fixes the corruption flag (State) when the profile folder is intact. Useful for the 'We can't sign in to your account' error.", "Examina os perfis de usuário no registro (ProfileList) e corrige o marcador de corrupção (State) quando a pasta do perfil está intacta. Útil para o erro 'Não foi possível entrar na sua conta'.", "Durchsucht Benutzerprofile in der Registrierung (ProfileList) und korrigiert das Korruptionskennzeichen (State), wenn der Profilordner intakt ist. Nützlich für den Fehler „Wir können uns nicht bei Ihrem Konto anmelden“.", "Analyse les profils utilisateur dans le registre (ProfileList) et corrige le marqueur de corruption (State) lorsque le dossier du profil est intact. Utile pour l'erreur « Impossible de se connecter à votre compte »."),
        ["Herramienta no reconocida"] = ("Unknown tool", "Ferramenta não reconhecida", "Unbekanntes Tool", "Outil inconnu"),
        ["{0} - Operación exitosa"] = ("{0} - Operation successful", "{0} - Operação bem-sucedida", "{0} - Vorgang erfolgreich", "{0} - Opération réussie"),
        ["{0} - Error"] = ("{0} - Error", "{0} - Erro", "{0} - Fehler", "{0} - Erreur"),
        ["{0} - Consola abierta"] = ("{0} - Console opened", "{0} - Console aberta", "{0} - Konsole geöffnet", "{0} - Console ouverte"),
        ["{0} - No se pudo abrir la consola elevada: {1}"] = ("{0} - Could not open the elevated console: {1}", "{0} - Não foi possível abrir o console elevado: {1}", "{0} - Erhöhte Konsole konnte nicht geöffnet werden: {1}", "{0} - Impossible d'ouvrir la console élevée : {1}"),
        ["Cerrar"] = ("Close", "Fechar", "Schließen", "Fermer"),

        // ===== Funciones, fixes y paneles (Herramientas / Panel de Windows) =====
        [".NET Framework (2, 3 y 4) - Activar"] = (".NET Framework (2, 3 and 4) - Enable", ".NET Framework (2, 3 e 4) - Ativar", ".NET Framework (2, 3 und 4) - Aktivieren", ".NET Framework (2, 3 et 4) - Activer"),
        ["Plataforma de desarrollo de Microsoft necesaria para ejecutar aplicaciones y juegos antiguos que dependen de .NET Framework."] = ("Microsoft development platform needed to run older apps and games that depend on .NET Framework.", "Plataforma de desenvolvimento da Microsoft necessária para executar aplicativos e jogos antigos que dependem do .NET Framework.", "Microsoft-Entwicklungsplattform, die zum Ausführen älterer Apps und Spiele erforderlich ist, die .NET Framework benötigen.", "Plateforme de développement Microsoft nécessaire pour exécuter les anciennes applications et jeux qui dépendent du .NET Framework."),
        ["Hyper-V - Activar"] = ("Hyper-V - Enable", "Hyper-V - Ativar", "Hyper-V - Aktivieren", "Hyper-V - Activer"),
        ["Plataforma de virtualización de Microsoft para crear y administrar máquinas virtuales. Requiere reinicio."] = ("Microsoft virtualization platform to create and manage virtual machines. Requires restart.", "Plataforma de virtualização da Microsoft para criar e gerenciar máquinas virtuais. Requer reinicialização.", "Microsoft-Virtualisierungsplattform zum Erstellen und Verwalten virtueller Maschinen. Erfordert Neustart.", "Plateforme de virtualisation Microsoft pour créer et gérer des machines virtuelles. Nécessite un redémarrage."),
        ["Componentes multimedia heredados (WMP, DirectPlay) - Activar"] = ("Legacy media components (WMP, DirectPlay) - Enable", "Componentes de mídia legados (WMP, DirectPlay) - Ativar", "Legacy-Mediakomponenten (WMP, DirectPlay) - Aktivieren", "Composants multimédia hérités (WMP, DirectPlay) - Activer"),
        ["Habilita programas antiguos de versiones anteriores de Windows (Windows Media Player, DirectPlay, componentes heredados)."] = ("Enables old programs from previous Windows versions (Windows Media Player, DirectPlay, legacy components).", "Habilita programas antigos de versões anteriores do Windows (Windows Media Player, DirectPlay, componentes legados).", "Aktiviert alte Programme früherer Windows-Versionen (Windows Media Player, DirectPlay, Legacy-Komponenten).", "Active les anciens programmes des versions précédentes de Windows (Windows Media Player, DirectPlay, composants hérités)."),
        ["Subsistema de Windows para Linux (WSL) - Activar"] = ("Windows Subsystem for Linux (WSL) - Enable", "Subsistema do Windows para Linux (WSL) - Ativar", "Windows-Subsystem für Linux (WSL) - Aktivieren", "Sous-système Windows pour Linux (WSL) - Activer"),
        ["Permite ejecutar distribuciones de Linux de forma nativa en Windows sin máquina virtual ni dual boot. Requiere reinicio."] = ("Allows running Linux distributions natively on Windows without a virtual machine or dual boot. Requires restart.", "Permite executar distribuições Linux nativamente no Windows sem máquina virtual nem dual boot. Requer reinicialização.", "Ermöglicht das native Ausführen von Linux-Distributionen unter Windows ohne virtuelle Maschine oder Dual-Boot. Erfordert Neustart.", "Permet d'exécuter des distributions Linux nativement sous Windows sans machine virtuelle ni double démarrage. Nécessite un redémarrage."),
        ["Sistema de archivos de red (NFS) - Activar"] = ("Network File System (NFS) - Enable", "Sistema de arquivos de rede (NFS) - Ativar", "Netzwerkdateisystem (NFS) - Aktivieren", "Système de fichiers réseau (NFS) - Activer"),
        ["Mecanismo para almacenar archivos en la red. Habilita el cliente NFS y la administración."] = ("Mechanism to store files on the network. Enables the NFS client and administration.", "Mecanismo para armazenar arquivos na rede. Habilita o cliente NFS e a administração.", "Mechanismus zum Speichern von Dateien im Netzwerk. Aktiviert den NFS-Client und die Verwaltung.", "Mécanisme pour stocker des fichiers sur le réseau. Active le client NFS et l'administration."),
        ["Copia de seguridad del registro (tarea diaria 00:30) - Activar"] = ("Registry backup (daily task 00:30) - Enable", "Backup do registro (tarefa diária 00:30) - Ativar", "Registrierungs-Backup (tägliche Aufgabe 00:30) - Aktivieren", "Sauvegarde du registre (tâche quotidienne 00:30) - Activer"),
        ["Habilita la copia de seguridad periódica del registro, desactivada por Microsoft desde Windows 10 1803. Crea una tarea programada diaria."] = ("Enables the periodic registry backup, disabled by Microsoft since Windows 10 1803. Creates a daily scheduled task.", "Habilita o backup periódico do registro, desativado pela Microsoft desde o Windows 10 1803. Cria uma tarefa agendada diária.", "Aktiviert das regelmäßige Registrierungs-Backup, das Microsoft seit Windows 10 1803 deaktiviert hat. Erstellt eine tägliche geplante Aufgabe.", "Active la sauvegarde périodique du registre, désactivée par Microsoft depuis Windows 10 1803. Crée une tâche planifiée quotidienne."),
        ["Recuperación F8 heredada - Activar"] = ("Legacy F8 recovery - Enable", "Recuperação F8 legada - Ativar", "Legacy-F8-Wiederherstellung - Aktivieren", "Récupération F8 héritée - Activer"),
        ["Habilita la pantalla de Opciones de arranque avanzadas (F8) para iniciar Windows en modos de solución de problemas."] = ("Enables the Advanced Boot Options (F8) screen to start Windows in troubleshooting modes.", "Habilita a tela de Opções avançadas de inicialização (F8) para iniciar o Windows em modos de solução de problemas.", "Aktiviert den Bildschirm „Erweiterte Startoptionen“ (F8), um Windows im Problembehandlungsmodus zu starten.", "Active l'écran des Options de démarrage avancées (F8) pour démarrer Windows dans les modes de dépannage."),
        ["Windows Sandbox - Activar"] = ("Windows Sandbox - Enable", "Windows Sandbox - Ativar", "Windows-Sandbox - Aktivieren", "Windows Sandbox - Activer"),
        ["Máquina virtual ligera que proporciona un escritorio temporal aislado para ejecutar aplicaciones de forma segura. Requiere reinicio."] = ("Lightweight virtual machine that provides an isolated temporary desktop to run apps safely. Requires restart.", "Máquina virtual leve que fornece uma área de trabalho temporária isolada para executar aplicativos com segurança. Requer reinicialização.", "Leichte virtuelle Maschine, die einen isolierten temporären Desktop zum sicheren Ausführen von Apps bereitstellt. Erfordert Neustart.", "Machine virtuelle légère qui fournit un bureau temporaire isolé pour exécuter des applications en toute sécurité. Nécessite un redémarrage."),
        ["Servidor NTP - Activar"] = ("NTP server - Enable", "Servidor NTP - Ativar", "NTP-Server - Aktivieren", "Serveur NTP - Activer"),
        ["Reemplaza el servidor horario predeterminado de Windows (time.windows.com) por pool.ntp.org para una sincronización más precisa y confiable."] = ("Replaces the default Windows time server (time.windows.com) with pool.ntp.org for more accurate and reliable synchronization.", "Substitui o servidor de horário padrão do Windows (time.windows.com) por pool.ntp.org para uma sincronização mais precisa e confiável.", "Ersetzt den Standard-Zeitserver von Windows (time.windows.com) durch pool.ntp.org für eine genauere und zuverlässigere Synchronisierung.", "Remplace le serveur horaire Windows par défaut (time.windows.com) par pool.ntp.org pour une synchronisation plus précise et fiable."),
        ["AutoLogon - Configurar"] = ("AutoLogon - Configure", "AutoLogon - Configurar", "AutoLogon - Konfigurieren", "AutoLogon - Configurer"),
        ["Configura el inicio de sesión automático de Windows. Pide usuario y contraseña, y los guarda en el registro (Winlogon)."] = ("Sets up automatic Windows sign-in. Asks for username and password and stores them in the registry (Winlogon).", "Configura o login automático do Windows. Pede usuário e senha e os salva no registro (Winlogon).", "Richtet die automatische Windows-Anmeldung ein. Fragt Benutzername und Kennwort ab und speichert sie in der Registrierung (Winlogon).", "Configure la connexion automatique à Windows. Demande un nom d'utilisateur et un mot de passe et les enregistre dans le registre (Winlogon)."),
        ["WinGet - Reinstalar"] = ("WinGet - Reinstall", "WinGet - Reinstalar", "WinGet - Neu installieren", "WinGet - Réinstaller"),
        ["Desinstala y reinstala el Instalador de aplicaciones (App Installer / WinGet) desde la última versión oficial del repositorio winget-cli."] = ("Uninstalls and reinstalls the App Installer (App Installer / WinGet) from the latest official release of the winget-cli repository.", "Desinstala e reinstala o Instalador de aplicativos (App Installer / WinGet) a partir da versão oficial mais recente do repositório winget-cli.", "Deinstalliert und installiert den App-Installer (App Installer / WinGet) aus der neuesten offiziellen Version des winget-cli-Repositorys neu.", "Désinstalle et réinstalle l'Installer d'applications (App Installer / WinGet) à partir de la dernière version officielle du dépôt winget-cli."),
